additional_options.availability:
{%- set pc = integration_entities('powercalc') -%}
{%- set ns = namespace(n=0) -%}
{%- for p in states.sensor | selectattr('attributes.device_class','defined') | selectattr('attributes.device_class','eq','power') | map(attribute='entity_id') | reject('in', pc) -%}
{%- set d = device_id(p) -%}
{%- if d -%}{%- set ents = device_entities(d) -%}
{%- if (ents | select('match','switch\.') | list) and not (ents | select('match','climate\.') | list) and is_number(states(p)) -%}{%- set ns.n = ns.n + 1 -%}{%- endif -%}{%- endif -%}
{%- endfor -%}
{{ ns.n > 0 }}

options.state:
{%- set pc = integration_entities('powercalc') -%}
{%- set ns = namespace(t=0, n=0) -%}
{%- for p in states.sensor | selectattr('attributes.device_class','defined') | selectattr('attributes.device_class','eq','power') | map(attribute='entity_id') | reject('in', pc) -%}
{%- set d = device_id(p) -%}
{%- if d -%}{%- set ents = device_entities(d) -%}
{%- if (ents | select('match','switch\.') | list) and not (ents | select('match','climate\.') | list) and is_number(states(p)) -%}
{%- set ns.t = ns.t + states(p) | float -%}{%- set ns.n = ns.n + 1 -%}
{%- endif -%}{%- endif -%}
{%- endfor -%}
{{ ns.t | round(0) if ns.n else none }}
